\label{main}
Let $\omega_0$ be a closed smooth real $(1,1)$-form with $\alpha=[\omega_0]$. Assume \eqref{strict} and the compatibility condition
\begin{equation}\label{compatibility}
 \int_X\bigl(\Lambda\wedge e^{\omega_0}\bigr)^{[n]}=0.
\end{equation}
Then the following are equivalent:
\begin{enumerate}[label=\textup{(\roman*)}]
\item There is a smooth closed representative
$\underline\omega=\omega_0+dd^c\underline u$ such that
$A_{\underline\omega}(x)\in\mathcal A$ for every $x\in X$.
\item There is a smooth admissible $\omega=\omega_0+dd^cu$
satisfying
\begin{equation}\label{target}
 P_x(A_\omega)=0.
\end{equation}
\end{enumerate}
$u$ is unique modulo constants.

\label{polarization}
For $G(\lambda)=\sum_{j=0}^d b_j\sigma_j(\lambda)$ with $b_d>0$ and $d\le n$,
the following are equivalent: $s\mapsto G(s\mathbf1)$ is right-Noetherian;
$s\mapsto G(s\mathbf1)$ is a univariate G\aa rding polynomial; $G$ is
G\aa rding; and $G$ is ideal G\aa rding.

\label{shiftlemma}
For every $x\in X$ and $b>-\delta(x)$, the polynomial $P_x-b$ is
ideal G\aa rding with first derived component $\mathcal A$, and
\begin{equation}\label{admissible-levels}
 P_x\le-\delta(x)\quad\text{on }\partial\mathcal A,
 \qquad \overline{\mathcal C_{P_x-b}}\subset\mathcal A.
\end{equation}

\label{C2prop}
For every finite $T$, each smooth solution of \eqref{path} satisfies
\begin{equation}\label{C2bound}
 \|dd^cv_t\|_{L^\infty}
 \le C_T\bigl(1+\|\partial v_t\|_{L^\infty}^2\bigr).
\end{equation}

\label{startprop}
Equation \eqref{path} has a smooth solution for every sufficiently
large $t$. Those solutions satisfy $\omega_t>0$.

\label{nhr:master}
Assume \ref{H1}--\ref{H2}. Let $\beta_1,\ldots,\beta_N$ be nef
classes, $\mathbf{x}=(x_1,\ldots,x_N)$, and
$0\le\varepsilon<\varepsilon_0$. The degree-$d$ homogeneous polynomial
\begin{equation}\label{nhr:homogenization}
 \mathcal T_{\alpha,\varepsilon}(y,\mathbf{x})
 =y^d\left[\mathcal I\!\left(\alpha+
        \frac1y\sum_{i=1}^N x_i\beta_i\right)+\varepsilon\right],
\end{equation}
with its polynomial extension at $y=0$, is Lorentzian.

\label{nhr:lefschetz}
The pairing $Q$ has signature $(1,h^{1,1}(X)-1)$, and cup product
induces an isomorphism
\begin{equation}\label{nhr:cup-isomorphism}
 \Theta\smile-:H^{1,1}(X,\mathbb R)
                   \longrightarrow H^{n-1,n-1}(X,\mathbb R).
\end{equation}
If $X$ is projective, the restriction to divisor classes has signature
$(1,\rho(X)-1)$, and the pairing induces an isomorphism
\begin{equation}\label{nhr:numerical-lefschetz}
 N^1(X)_{\mathbb R}\longrightarrow
 N^1(X)_{\mathbb R}^{*}\simeq N_1(X)_{\mathbb R},
 \qquad u\longmapsto\left(v\longmapsto\int_Xuv\Theta\right).
\end{equation}
